import re

_PATTERN = re.compile(
    r" *(?:([0-9]+)d)? *(?:([0-9]+)h)? *(?:([0-9]+)m)? *(?:([0-9]+)s)? *"
)

_UNIT_SECONDS = (86400, 3600, 60, 1)


def _digits_to_int(digits: str) -> int:
    # Python 3.12 の int() は既定で 4300 桁を超える文字列を拒否するため、長い数は分割して変換する
    if len(digits) <= 4000:
        return int(digits)
    half = len(digits) // 2
    high = _digits_to_int(digits[:half])
    low = _digits_to_int(digits[half:])
    return high * 10 ** (len(digits) - half) + low


def parse_duration(text: str) -> int:
    if not isinstance(text, str):
        raise ValueError("text must be a str")
    match = _PATTERN.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid duration: {text!r}")
    groups = match.groups()
    if all(group is None for group in groups):
        raise ValueError(f"invalid duration: {text!r}")
    total = 0
    for digits, unit_seconds in zip(groups, _UNIT_SECONDS):
        if digits is not None:
            total += _digits_to_int(digits) * unit_seconds
    return total
